"}}},{"SCYTHER",{["value"]={["kind"]="LOUVA-DEUS",["text"]="Ao se mover, vira<NEXT>um borrão. Suas<NEXT>cores o tornam",["text2"]="invisível quando<NEXT>se esconde no<NEXT>mato."}}},{"SEADRA",{["value"]={["kind"]="DRAGÃO",["text"]="As pontas das<NEXT>nadadeiras soltam<NEXT>veneno. Elas e",["text2"]="seus ossos são<NEXT>valiosos na<NEXT>medicina natural."}}},{"SEAKING",{["value"]={["kind"]="PEIXE-OURO",["text"]="Fura rochas no<NEXT>leito do rio com o<NEXT>chifre. Os ninhos",["text2"]="impedem que a água<NEXT>leve os ovos."}}},{"SEEL",{["value"]={["kind"]="LEÃO-MAR.",["text"]="De dia, costuma<NEXT>dormir no fundo de<NEXT>águas rasas. Fecha",["text2"]="as narinas ao<NEXT>nadar."}}},{"SENTRET",{["value"]={["kind"]="SENTINELA",["text"]="Fica sobre a cauda<NEXT>para ver longe. Se<NEXT>avista um inimigo,",["text2"]="grita alto para<NEXT>alertar os outros."}}},{"SHELLDER",{["value"]={["kind"]="BIVALVE",["text"]="Grãos de areia na<NEXT>concha se misturam<NEXT>aos fluidos do",["text2"]="corpo e formam<NEXT>lindas pérolas."}}},{"SHUCKLE",{["value"]={["kind"]="MOFO",["text"]="Guarda FRUTAS na<NEXT>concha. Para<NEXT>evitar ataques,",["text2"]="esconde-se sob<NEXT>rochas e fica<NEXT>totalmente imóvel."}}},{"SKARMORY",{["value"]={["kind"]="AVE ARMADA",["text"]="Faz ninhos entre<NEXT>espinhos. Os<NEXT>arranhões deixam",["text2"]="duras as asas dos<NEXT>filhotes."}}},{"SKIPLOOM",{["value"]={["kind"]="ALGODÃO",["text"]="Abre as pétalas<NEXT>para absorver luz<NEXT>solar. Também",["text2"]="flutua no ar para<NEXT>chegar mais perto<NEXT>do sol."}}},{"SLOWBRO",{["value"]={["kind"]="EREMITA",["text"]="Já era distraído<NEXT>por natureza. Com<NEXT>o veneno que",["text2"]="SHELLDER libera,<NEXT>perdeu a sensação<NEXT>de dor."}}},{"SLOWKING",{["value"]={["kind"]="REAL",["text"]="Uma mordida na<NEXT>cabeça de SLOWPOKE<NEXT>levou toxinas ao",["text2"]="cérebro e liberou<NEXT>um poder<NEXT>extraordinário."}}},{"SLOWPOKE",{["value"]={["kind"]="LERDO",["text"]="A ponta da cauda<NEXT>solta uma seiv